-- bank-seed del 3 av 8. Klistra in allt och kör (Run). Kör delarna i ordning.
begin;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-satsbrada-volt-rygg', 'techniques', 'Satsbräda volt till rygg', 9, 'Volt från satsbräda till landning på rygg — progressiv volt med madrass.', '1. Säkerställ madrass som räcker bakåt innan första försöket.
2. Satsbräda → rotation → landning på rygg.
3. Bygg från kortare rotation innan fullare volt; spotta efter nivå.
4. En i taget.', 'För lite rotation (nacke/huvud); för mycket höjd utan kontroll; madrassen måste räcka bakåt.', true, 'Madrassen måste räcka bakåt innan första försöket. En i taget.', 'tech-board-volt-back', 'easy', array['teknik', 'vault', 'new-coach-ok']::text[], '[{"pieceId":"eq-satsbrada","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, false, true, false, null, 150, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-trampett-volt-mattberg', 'techniques', 'Trampett volt upp på mattberg', 9, 'Volt från trampett upp på mattberg — progressiv höjd och rotation.', '1. Kolla att mattberget är stabilt och högt nog.
2. Ansats → trampett → volt → landning högt på mattberg.
3. Progressera höjd/rotation efter nivå.
4. En i taget; nästa väntar tills landningen är klar.', 'Mattberg som tippar eller är för lågt; underrotation; att nästa gymnast startar för tidigt.', true, 'Mattberget ska stå stabilt. Nästa väntar tills landningen är klar.', 'tech-trampett-mattberg', 'easy', array['teknik', 'trampett', 'new-coach-ok']::text[], '[{"pieceId":"eq-trampett","count":1},{"pieceId":"eq-mattberg","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, false, true, false, null, 160, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-rondat-flickis', 'techniques', 'Rondat–flickis', 10, 'Rondat till flickis (bakåtväxel / flic-flac) — endast med erfaren ledare och aktiv spotting.', '1. Endast när erfaren ledare leder och spotttar.
2. Progressera från bekanta delar innan hela kedjan.
3. Spotting aktivt under hela setet.
4. Avbryt om tekniken fallerar.', 'Handplacering, axellinje, underrotation, nacke. Avbryt om tekniken fallerar under setet.', true, 'Endast med erfaren ledare och aktiv spotting. Avbryt om tekniken fallerar.', 'tech-rondat-flickis', 'hard', array['teknik', 'floor', 'experienced-coach-only']::text[], '[{"pieceId":"eq-tumblingmatta","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, true, false, false, null, 170, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-flickis-kudde', 'techniques', 'Flickis med flickiskudde', 9, 'Flickis med flickiskudde som stöd — känna bakåtrörelsen innan fri flickis.', '1. Placera kudden enligt klubbens metod.
2. Låt gymnasten känna bakåtrörelsen med stöd.
3. Progressera mot friare flickis när formen sitter.', 'Kudden rätt placerad; inte ”kasta” bakåt utan aktivt handstöd från gymnasten där metoden kräver det.', true, 'Kudden enligt klubbens metod. Kasta inte bakåt utan handstöd.', 'tech-flickis-pad', 'easy', array['teknik', 'floor', 'new-coach-ok']::text[], '[{"pieceId":"eq-flickiskudde","count":1},{"pieceId":"eq-madrass","count":1}]'::jsonb, null, null, null, false, true, false, null, 180, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-falla-bakat-hojd', 'techniques', 'Falla bakåt från höjd till rygg', 6, 'Kontrollerad fall bakåt från höjd till landning på rygg — trygghet inför bakåtmoment.', '1. Använd plint/höjd som klubben brukar; tjock och lång madrass bakom.
2. Falla bakåt till rygg med teknikfokus.
3. Bygg trygghet stegvis — ingen ”vem vågar högst”-lek.', 'Huvudet får inte ta emot; madrass tillräckligt tjock/lång; ingen höjdtävling utan teknikfokus.', true, 'Tjock och lång madrass bakom. Huvudet får inte ta emot.', 'tech-fall-back', 'easy', array['teknik', 'floor', 'new-coach-ok']::text[], '[{"pieceId":"eq-plint","count":1},{"pieceId":"eq-madrass","count":1}]'::jsonb, null, null, null, false, true, false, null, 190, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-salto-fran-hojd', 'techniques', 'Salto från höjd', 9, 'Salto från höjd (fullare voltmoment) — endast med erfaren ledare, spotting och rätt uppbyggnad.', '1. Endast med erfaren ledare och rätt progression bakom.
2. Spotting och madrassuppställning före första försöket.
3. En i taget; stoppa tidigt vid osäkra försök.', 'Under-/överrotation; landningszon; trötthet i kön. Stoppa tidigt vid osäkra försök.', true, 'Endast med erfaren ledare, spotting och madrass före första försöket. Stoppa osäkra försök.', 'tech-salto-height', 'hard', array['teknik', 'floor', 'experienced-coach-only']::text[], '[{"pieceId":"eq-plint","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, true, false, false, null, 200, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-handstaende-falla-rygg', 'techniques', 'Handstående falla till rygg', 6, 'Från handstående, kontrollerad fall till rygg — öppning och trygg bakåtlandning.', '1. Lägg madrass bakom innan någon går upp i handstående.
2. Handstående (mot vägg eller fri enligt nivå) → tippa/falla till rygg.
3. Cue öppning och mjuk landning på rygg.', 'Huvud/nacke; axlar som kollapsar; madrass bakom måste finnas innan de går upp.', true, 'Madrass bakom innan någon går upp i handstående.', 'tech-hs-fall-back', 'easy', array['teknik', 'floor', 'new-coach-ok']::text[], '[{"pieceId":"eq-madrass","count":1}]'::jsonb, null, null, null, false, true, false, null, 210, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
